public class InnerConnectionOAuth2PropertiesFactory(Action<Humidifier.DataZone.ConnectionTypes.OAuth2Properties> factoryAction = null) : SubResourceFactory<Humidifier.DataZone.ConnectionTypes.OAuth2Properties>
{

    internal InnerConnectionAuthorizationCodePropertiesFactory AuthorizationCodePropertiesFactory { get; set; }

    internal InnerConnectionOAuth2ClientApplicationFactory OAuth2ClientApplicationFactory { get; set; }

    internal InnerConnectionGlueOAuth2CredentialsFactory OAuth2CredentialsFactory { get; set; }

    protected override Humidifier.DataZone.ConnectionTypes.OAuth2Properties Create()
    {
        var oAuth2PropertiesResult = CreateOAuth2Properties();
        factoryAction?.Invoke(oAuth2PropertiesResult);

        return oAuth2PropertiesResult;
    }

    private Humidifier.DataZone.ConnectionTypes.OAuth2Properties CreateOAuth2Properties()
    {
        var oAuth2PropertiesResult = new Humidifier.DataZone.ConnectionTypes.OAuth2Properties();

        return oAuth2PropertiesResult;
    }
    public override void CreateChildren(Humidifier.DataZone.ConnectionTypes.OAuth2Properties result)
    {
        base.CreateChildren(result);

        result.AuthorizationCodeProperties ??= AuthorizationCodePropertiesFactory?.Build();
        result.OAuth2ClientApplication ??= OAuth2ClientApplicationFactory?.Build();
        result.OAuth2Credentials ??= OAuth2CredentialsFactory?.Build();
    }

} // End Of Class

